        "e": "ตอบข้อ ข (10 ปี) — สมมติให้ ประชากรทั้งสองหมู่บ้านมีจำนวนเท่ากันเมื่อเวลา x ปี ประชากรในหมู่บ้านบัวขาวมีจำนวน 6,000 คนและมีอัตราลดลงปีละ 140 คน เมื่อเวลา x ปี จำนวนประชากรในหมู่บ้านบัวขาว = 6,000 - 140x คน ประชากรในหมู่บ้านบัวแดงมีจำนวน 4,000 คนและมีอัตราเพิ่มขึ้นปีละ 60 คน เมื่อเวลา x ปี จำนวนประชากรในหมู่บ้านบัวแดง = 4,000 + 60x คน ประชากรในหมู่บ้านบัวขาว = ประชากรในหมู่บ้านบัวแดง 6,000 - 140x = 4,000 + 60x 6,000 - 4,000 = 60x + 140x 2,000 = 200x x = 200 2,000 x = 10 ∴ จำนวนประชากรทั้ง 2 หมู่บ้านเท่ากันในอีก 10 ปีข้างหน้า",
